<div class="recipe-layout">
    <section class="panel"><div class="panel-heading"><div><h3>Komposisi <?= e($chosenProduct['name']) ?></h3><p>Masukkan kuantitas bahan untuk satu kali produksi; jumlah mengikuti satuan dasar setiap bahan tanpa konversi otomatis.</p></div></div>
        <?php if (!$ingredients): ?><div class="notice notice-warning">Bahan baku belum tersedia. Tambahkan bahan terlebih dahulu pada halaman <a href="?page=ingredients">Bahan Baku</a>.</div><?php endif; ?>
        <form method="post" class="form-stack">
            <input type="hidden" name="_csrf" value="<?= e(\App\Core\Csrf::token()) ?>"><input type="hidden" name="action" value="save_recipe"><input type="hidden" name="return_page" value="recipes"><input type="hidden" name="product_id" value="<?= $selected_id ?>">
            <label>Hasil produksi (<?= e($chosenProduct['unit']) ?>)<input type="number" name="yield_quantity" min="0.001" step="0.001" value="<?= e($formYield) ?>" required><small>Jumlah unit yang dihasilkan satu batch; gunakan titik untuk desimal.</small></label>
