            <?php for ($i = 0; $i < $formRowCount; $i++): $selectedIngredient = $formIngredientIds[$i] ?? '0'; ?>
            <div class="recipe-row"><select name="ingredient_id[]" aria-label="Bahan baku <?= $i + 1 ?>"><option value="0">Pilih bahan</option><?php foreach ($ingredients as $ingredient): ?><option value="<?= (int) $ingredient['id'] ?>" <?= (int) $selectedIngredient === (int) $ingredient['id'] ? 'selected' : '' ?>><?= e($ingredient['name']) ?> · <?= (float) $ingredient['average_cost'] > 0 ? rupiah($ingredient['average_cost']) : 'biaya belum diisi' ?>/<?= e($ingredient['unit']) ?></option><?php endforeach; ?></select><input type="number" name="quantity[]" min="0.001" step="0.001" value="<?= e($formQuantities[$i] ?? '') ?>" aria-label="Jumlah bahan <?= $i + 1 ?>" placeholder="mis. 0.5"></div>
