        <?php if ($recipe_items): ?><div class="panel-heading"><div><h3>Bahan tersimpan</h3><p>Hapus satu bahan secara terpisah dengan konfirmasi; stok tidak berubah.</p></div></div><ul class="simple-list"><?php foreach ($recipe_items as $item): $ingredient = null; foreach ($ingredients as $candidate) { if ((int) $candidate['id'] === (int) $item['ingredient_id']) { $ingredient = $candidate; break; } } ?><li><span><strong><?= e($ingredient['name'] ?? 'Bahan tidak tersedia') ?></strong><small><?= e(format_quantity($item['quantity'])) ?> <?= e($ingredient['unit'] ?? '') ?> per batch</small></span><details class="confirm-action"><summary>Hapus bahan</summary><form method="post" class="confirm-box"><input type="hidden" name="_csrf" value="<?= e(\App\Core\Csrf::token()) ?>"><input type="hidden" name="action" value="delete_recipe_ingredient"><input type="hidden" name="return_page" value="recipes"><input type="hidden" name="product_id" value="<?= $selected_id ?>"><input type="hidden" name="ingredient_id" value="<?= (int) $item['ingredient_id'] ?>"><p>Hapus <?= e($ingredient['name'] ?? 'bahan ini') ?> dari resep <?= e($chosenProduct['name']) ?>? Kuantitas resep dan HPP akan diperbarui; stok tidak berubah.</p><button class="button" type="submit">Ya, hapus dari resep</button></form></details></li><?php endforeach; ?></ul><?php endif; ?>
