<section class="panel table-panel"><div class="panel-heading"><div><h3>Ringkasan HPP produk</h3><p>Nilai dihitung dari resep dan biaya rata-rata bahan baku aktif.</p></div></div>
<div class="table-wrap"><table><thead><tr><th>Produk</th><th>HPP / unit</th><th>Harga jual</th><th>Margin</th><th>Saran harga</th><th>Resep</th></tr></thead><tbody>
<?php foreach ($costs as $product): if ($product['type'] !== 'culinary') { continue; } $costAvailable = $product['current_cost'] !== null; $hasRecipeItems = (int) $product['recipe_item_count'] > 0; $hasValidYield = $product['recipe_yield_quantity'] !== null && (float) $product['recipe_yield_quantity'] > 0; $cost = $costAvailable ? (float) $product['current_cost'] : 0.0; $price = (float) $product['selling_price']; $margin = $costAvailable && $price > 0 ? ($price - $cost) / $price * 100 : null; $recommended = $costAvailable && $price > 0 && (float) $product['target_margin'] < 100 ? $cost / (1 - (float) $product['target_margin'] / 100) : null; $recipeStatus = !$hasRecipeItems ? 'Resep belum dibuat' : (!empty($product['missing_cost_ingredients']) ? 'Biaya bahan belum lengkap' : (!$hasValidYield ? 'Resep perlu diperiksa' : 'Resep dan biaya siap')); ?>
<tr><td class="strong"><?= e($product['name']) ?><?php if (!$costAvailable && $hasRecipeItems && !empty($product['missing_cost_ingredients'])): ?><small class="cell-sub">Harga belum diisi: <?= e($product['missing_cost_ingredients']) ?></small><?php endif; ?></td><td><?= $costAvailable ? rupiah($cost) : '<span class="badge badge-warning">HPP belum tersedia</span>' ?></td><td><?= rupiah($price) ?></td><td class="<?= $margin === null ? 'muted' : ($margin < (float) $product['min_margin'] ? 'margin-danger' : 'margin-good') ?>"><?= $margin === null ? '—' : number_format($margin, 1, ',', '.') . '%' ?></td><td><?= $recommended === null ? '—' : rupiah($recommended) ?></td><td><span class="badge <?= !$hasRecipeItems ? 'badge-gray' : (!$costAvailable ? 'badge-warning' : 'badge-green') ?>"><?= e($recipeStatus) ?></span> <a class="text-link" href="?page=recipes&product_id=<?= (int) $product['id'] ?>">Atur resep →</a></td></tr>
<?php endforeach; ?></tbody></table></div>
</section>
